tableData:
{{
  (() => {
    // ⚠️ Remplace Get_Commandes_Clients ci-dessous par le nom exact de ta requête
    const data = Get_Commandes_Clients.data || [];
    let groupedData = [];

    // 1. Comptage par statut
    let counts = {};
    data.forEach(row => {
      let st = row.Statut || "Non défini";
      counts[st] = (counts[st] || 0) + 1;
    });

    // 2. Regroupement avec lignes d'en-tête
    let currentStatut = null;
    data.forEach((row) => {
      let st = row.Statut || "Non défini";

      if (st !== currentStatut) {
        let emoji = "📁";
        const cleanSt = st.toUpperCase().replace(/^[^A-ZÀ-Ÿ0-9]+/, '').trim();

        if (cleanSt.includes('ACTION REQUISE')) emoji = '⚠️';
        else if (cleanSt.includes('COMMANDE COMPLETE') || cleanSt.includes('COMMANDE COMPLÈTE')) emoji = '📦';
        else if (cleanSt.includes('PIECE A COMMANDER') || cleanSt.includes('PIÈCE À COMMANDER')) emoji = '🛒';
        else if (cleanSt.includes('PIECE EN COMMANDE') || cleanSt.includes('PIÈCE EN COMMANDE')) emoji = '🚚';
        else if (cleanSt.includes('EN ATTENTE')) emoji = '⏳';
        else if (cleanSt.includes('FACTURE') || cleanSt.includes('FACTURÉ')) emoji = '🧾';

        const cleanLabel = st.replace(/^[⚠️📦🛒🚚⏳🧾📁\s]+/, '').trim();

        groupedData.push({
          isHeader: true,
          Client: `${emoji} ${cleanLabel} (${counts[st]})`,
          Societe: `${emoji} ${cleanLabel} (${counts[st]})`,
          Nom: "",
          "N° COMMANDE": "",
          N_COMMANDE_CLIENT: "",
          Statut: "",
          TOTAL_TTC: "",
          Date: "",
          Notes: "",
          Montant_Acompte_TTC: "",
          ID_Commande_Client: null
        });
        currentStatut = st;
      }

      groupedData.push({ ...row, isHeader: false });
    });

    return groupedData;
  })()
}}
